		componentDidCatch(err) {
			spy();
			errored = err;
			this.forceUpdate();
		}

		render(props, state) {
			if (errored) {
				return <p>Error</p>;
			}

			return <Fragment>{props.page === 1 ? <Page1 /> : <Page2 />}</Fragment>;
		}
